  const kk = clamp(sj.t / (sj.dur || 1.2), 0, 1);
  speedT = 0.55 + 0.45 * Math.abs(Math.cos(kk * Math.PI));   // fast launch, float at the apex, dive
  stretchT = 0.06 * (0.4 + 0.6 * Math.abs(Math.cos(kk * Math.PI)));
